//! Concrete inventory audited from the Swift package on 2026-07-18.
//!
//! Core ML hashes describe the extracted `.mlmodelc` directory using
//! [`crate::sha256_path`] — the same bytes the July zips carried, now served as
//! a prefix of objects. The second digest beside each one is the pin for the
//! manifest that names those objects, generated by `scripts/models-publish`.
//! An explicit `Missing` artifact is intentional: it makes unfinished exports
//! visible to tooling instead of silently omitting them.

use ferment_engine_infer::ModelId;

use crate::{
    ArtifactSource, BackendKind, CoreMlComputeUnits, ModelArtifact, ModelDefinition, ModelManifest,
    OrtPlacement, Placement, ResourceDefinition,
};

use CoreMlComputeUnits::{CpuAndNeuralEngine, CpuOnly};

mod coreai;
mod mert;
mod retrieval;

/// Where the iOS pipeline originally published the compiled Core ML zips.
/// Provenance only — Studio downloads everything from its own CDN below.
pub const SWIFT_MODEL_BASE_URL: &str = "https://public.lockvoid.com/ferment/ios/models";
// 2026-08-31.2: the Core ML tier moves from zips to prefix+manifest delivery.
// The BYTES are unchanged — every tree digest below is the one taken over the
// July zips' contents — but the on-disk root is versioned, so a bump here is
// what gives Core ML users a clean re-download onto the new lane instead of a
// cache half-installed by the old one. ONNX users re-fetch too; that is the
// price of one root per fleet version, and it is the same price that made
// 2026-08-31.1 safe.
//
// 2026-09-21.1: `dasheng_base_mel` — the first family exported by
// `ferment-models-export` and served from `MODEL_BASE_URL`. New bytes under a
// new name on both lanes, so the root moves.
//
// 2026-09-22.1: `music_tagger_heads` follows it there — same name and door,
// new bytes on both lanes (a static batch-1 ONNX, a Core ML bundle that is
// float16 at both doors), so the root moves again.
//
// 2026-09-22.2: `autoshot` (the device bundle loses its `_fp16` suffix) and
// `music_highlighter` (its output is `logits` by name) follow, new bytes on
// every lane.
pub const MODEL_FLEET_VERSION: &str = "2026-09-23.1";
/// The ONE root every platform reads — iOS, Android, Studio. Every object on
/// it is a prefix plus its manifest, whatever back-end it belongs to:
/// `<name>.mlmodelc`, `<name>.<arch>.aimodelc`, `<name>.onnx`. Staged and
/// verified by `ferment-models-export` (`uv run publish <model>`).
pub const MODEL_BASE_URL: &str = "https://public.lockvoid.com/ferment/models";

const MODEL_VERSION: &str = "1";

